path1='/Users/archismanpal2007/Desktop/SnAI/demo_logs.log'path2='/Users/archismanpal2007/Desktop/SnAI/error.log'path3='/Users/archismanpal2007/Desktop/SnAI/info.log'with open(path1,'r') as file1:    for line in file1.readlines():        if 'ERROR' in line:            with open(path2,'a') as file2:                file2.write(line)        elif 'INFO' in line:            with open(path3,'a') as file3:                file3.write(line)